session_start();require_once __DIR__.'/includes/config.php';if(empty($_SESSION['alogin'])||empty($_SESSION['uid'])){header('Location: index.php');exit;}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$id=(int)($_GET['id']??$_POST['jornada_id']??0);if(!$id){header('Location: manage-mantenimientos.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$accion=$_POST['accion']??'';try{
 if($accion==='iniciar'){$q=$dbh->prepare("UPDATE jornadas_mantenimiento SET estado='EN_EJECUCION',fecha_hora_inicio=NOW() WHERE id=? AND estado='PROGRAMADA'");$q->execute([$id]);if(!$q->rowCount())throw new Exception('La jornada ya fue iniciada o no está disponible.');$dbh->prepare("UPDATE mantenimientos SET fecha_hora_inicio=NOW() WHERE jornada_id=? AND fecha_hora_inicio IS NULL")->execute([$id]);}
 elseif($accion==='resultado'){$mid=(int)$_POST['mantenimiento_id'];$estado=$_POST['estado_atencion']??'';$novedad=trim($_POST['novedad']??'');$trabajo=trim($_POST['trabajo_realizado']??'');if(!in_array($estado,['REALIZADO','NOVEDAD','NO_REALIZADO'],true))throw new Exception('Seleccione un resultado válido.');if(in_array($estado,['NOVEDAD','NO_REALIZADO'],true)&&$novedad==='')throw new Exception('Describa la novedad o justificación.');$q=$dbh->prepare("UPDATE mantenimientos SET estado_atencion=?,novedad=?,trabajo_realizado=? WHERE id=? AND jornada_id=?");$q->execute([$estado,$novedad?:null,$trabajo?:null,$mid,$id]);}
 elseif($accion==='cerrar'){$dbh->beginTransaction();$j=$dbh->prepare("SELECT * FROM jornadas_mantenimiento WHERE id=? FOR UPDATE");$j->execute([$id]);$jour=$j->fetch();if(!$jour||$jour['estado']!=='EN_EJECUCION')throw new Exception('Solo se puede cerrar una jornada en ejecución.');$q=$dbh->prepare("SELECT COUNT(*) FROM mantenimientos WHERE jornada_id=? AND estado_atencion='PENDIENTE'");$q->execute([$id]);if((int)$q->fetchColumn()>0)throw new Exception('Hay equipos sin resultado. Marque cada equipo como realizado, con novedad o no realizado.');
  $items=$dbh->prepare("SELECT id,activo_id,estado_atencion,trabajo_realizado,novedad FROM mantenimientos WHERE jornada_id=? FOR UPDATE");$items->execute([$id]);foreach($items->fetchAll() as $m){if($m['estado_atencion']==='REALIZADO' || $m['estado_atencion']==='NOVEDAD'){$resultado=$m['estado_atencion']==='REALIZADO'?'OPERATIVO':'OPERATIVO_CON_OBSERVACIONES';$proxima=$jour['proxima_fecha_manual'];if($jour['periodicidad_meses']){$calc=$dbh->prepare("SELECT DATE_ADD(CURDATE(), INTERVAL ? MONTH)");$calc->execute([(int)$jour['periodicidad_meses']]);$proxima=$calc->fetchColumn();}$dbh->prepare("UPDATE mantenimientos SET resultado=?,fecha_finalizacion=CURDATE(),proximo_mantenimiento=? WHERE id=?")->execute([$resultado,$proxima,$m['id']]);$dbh->prepare("UPDATE activos SET fecha_mantenimiento=CURDATE(),fecha_actualizacion=NOW() WHERE id=?")->execute([$m['activo_id']]);}else{$dbh->prepare("UPDATE mantenimientos SET resultado='PENDIENTE',fecha_finalizacion=NULL WHERE id=?")->execute([$m['id']]);}}
  $dbh->prepare("UPDATE mantenimientos SET fecha_hora_fin=NOW(),tiempo_ejecucion_segundos=TIMESTAMPDIFF(SECOND,fecha_hora_inicio,NOW()) WHERE jornada_id=?")->execute([$id]);$dbh->prepare("UPDATE jornadas_mantenimiento SET estado='CERRADA',fecha_hora_cierre=NOW(),tiempo_total_segundos=TIMESTAMPDIFF(SECOND,fecha_hora_inicio,NOW()) WHERE id=?")->execute([$id]);$dbh->prepare("INSERT INTO auditoria(usuario_id,tabla_afectada,registro_id,accion,descripcion,direccion_ip) VALUES(?, 'jornadas_mantenimiento', ?, 'UPDATE', ?, ?)")->execute([(int)$_SESSION['uid'],$id,'Cierre de jornada. Se actualizaron hojas de vida de activos atendidos; los no realizados permanecen pendientes.',$_SERVER['REMOTE_ADDR']??null]);$dbh->commit();header('Location: ejecutar-jornada.php?id='.$id.'&cerrada=1');exit;}
 }catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();$error=$e->getMessage();}}
$q=$dbh->prepare("SELECT * FROM jornadas_mantenimiento WHERE id=?");$q->execute([$id]);$j=$q->fetch();if(!$j){http_response_code(404);exit('Jornada no encontrada.');}$q=$dbh->prepare("SELECT m.*,a.codigo_inventario,a.descripcion activo,s.nombre sede,u.nombre ubicacion FROM mantenimientos m JOIN activos a ON a.id=m.activo_id LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id LEFT JOIN sedes s ON s.id=u.sede_id WHERE m.jornada_id=? ORDER BY a.codigo_inventario");$q->execute([$id]);$items=$q->fetchAll();$pend=0;$real=0;$nov=0;$no=0;foreach($items as $x){if($x['estado_atencion']==='PENDIENTE')$pend++;elseif($x['estado_atencion']==='REALIZADO')$real++;elseif($x['estado_atencion']==='NOVEDAD')$nov++;else $no++;}
include __DIR__.'/includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include __DIR__.'/includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-sm-12"><h2 class="title">Jornada de mantenimiento #<?=$id?></h2><p><?=h($j['nombre'])?> | <?=h($j['fecha_programada'])?></p></div></div></div><section class="section"><div class="container-fluid"><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['cerrada'])):?><div class="alert alert-success">Jornada cerrada. Las hojas de vida de los equipos atendidos fueron actualizadas.</div><?php endif;?>
<div class="panel"><div class="panel-body p-20"><div class="row"><div class="col-md-3"><strong>Estado:</strong> <?=h($j['estado'])?></div><div class="col-md-3"><strong>Equipos:</strong> <?=count($items)?></div><div class="col-md-2"><strong>Realizados:</strong> <?=$real?></div><div class="col-md-2"><strong>Con novedad:</strong> <?=$nov?></div><div class="col-md-2"><strong>Pendientes:</strong> <?=$pend?></div></div><hr><div class="row"><div class="col-md-6"><h3 id="timer">00:00:00</h3><small>Tiempo transcurrido desde el inicio</small></div><div class="col-md-6 text-right"><?php if($j['estado']==='PROGRAMADA'):?><form method="post"><input type="hidden" name="jornada_id" value="<?=$id?>"><input type="hidden" name="accion" value="iniciar"><button class="btn btn-success">Iniciar mantenimiento</button></form><?php elseif($j['estado']==='EN_EJECUCION'):?><form method="post" onsubmit="return confirm('¿Cerrar la jornada? Los equipos no realizados permanecerán pendientes de atención.');"><input type="hidden" name="jornada_id" value="<?=$id?>"><input type="hidden" name="accion" value="cerrar"><button class="btn btn-danger" <?=$pend?'disabled':''?>>Cerrar mantenimiento</button></form><?php endif;?></div></div></div></div>
<div class="panel"><div class="panel-heading"><h5>Equipos de la jornada y resultados</h5></div><div class="panel-body p-20"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Código / activo</th><th>Ubicación</th><th>Resultado</th><th>Trabajo realizado / novedad</th><th>Acción</th></tr></thead><tbody><?php foreach($items as $m):?><tr><td><strong><?=h($m['codigo_inventario'])?></strong><br><?=h($m['activo'])?></td><td><?=h($m['sede'])?> / <?=h($m['ubicacion'])?></td><td><?=h($m['estado_atencion'])?></td><td><?=h($m['trabajo_realizado'])?><br><span class="text-danger"><?=h($m['novedad'])?></span></td><td><?php if($j['estado']==='EN_EJECUCION'):?><form method="post"><input type="hidden" name="jornada_id" value="<?=$id?>"><input type="hidden" name="accion" value="resultado"><input type="hidden" name="mantenimiento_id" value="<?=$m['id']?>"><select name="estado_atencion" class="form-control" required><option value="PENDIENTE" <?=$m['estado_atencion']==='PENDIENTE'?'selected':''?>>Pendiente</option><option value="REALIZADO">Realizado</option><option value="NOVEDAD">Con novedad</option><option value="NO_REALIZADO">No realizado</option></select><textarea name="trabajo_realizado" class="form-control" rows="2" placeholder="Trabajo realizado"><?=h($m['trabajo_realizado'])?></textarea><textarea name="novedad" class="form-control" rows="2" placeholder="Novedad / justificación (obligatoria si aplica)"><?=h($m['novedad'])?></textarea><button class="btn btn-primary btn-xs" style="margin-top:5px">Guardar resultado</button></form><?php else:?><span class="text-muted">Jornada cerrada</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div><a href="manage-mantenimientos.php" class="btn btn-default">Volver a mantenimientos</a></div></section></div></div></div>
<script>var start=<?= $j['fecha_hora_inicio']?json_encode(strtotime($j['fecha_hora_inicio'])):'null' ?>;function tick(){if(!start)return;var s=Math.max(0,Math.floor(Date.now()/1000)-start);var h=String(Math.floor(s/3600)).padStart(2,'0'),m=String(Math.floor(s%3600/60)).padStart(2,'0'),x=String(s%60).padStart(2,'0');document.getElementById('timer').textContent=h+':'+m+':'+x;}tick();setInterval(tick,1000);</script><?php include __DIR__.'/includes/footer.php';?>